section.programlisting:
function row_count(y: int, n: int) returns int { let ci (2.0 * (y as double) / (n as double)) - 1.0 var count 0 var x 0 while x < n { let cr (2.0 * (x as double) / (n as double)) - 1.5 var zr: double 0.0 var zi: double 0.0 var i 0 var inside true while i < 50 and inside { let tr zr * zr - zi * zi + cr zi := 2.0 * zr * zi + ci zr := tr if zr * zr + zi * zi > 4.0 inside := false i := i + 1 } if inside count := count + 1 x := x + 1 } count }
let n 2000 var counts Vector[int](n as size_t) for y in n counts.put(y as size_t, row_count(y, n))
var total 0 for c in counts total := total + c print "mandelbrot `n`: `total` points inside"

listitem.para:
read anything that does not change while the loop
        runs: the loop variable, bindings made before the loop, the
        elements of a vector;

call functions, which read and return and do nothing
        else (), and procedures that
        write only what the round made itself;

make values of their own — bindings inside the body,
        strings, records — which are gone when the round
        ends unless the round keeps them;

section.programlisting:
function cube(x: int) returns int x * x * x
var cubes Array[int]() for i in 6 cubes.add(cube(i))
var last 0 for i in 6 last := cube(i)
var first 0 for i in 6 { if cube(i) > 50 { first := i break } } print "`cubes.length` cubes, the last `last`, the first above 50: `first`"

function term(k: int) returns double
{
    let t 4.0 / ((2 * k + 1) as double)
    if k % 2 = 0: t else 0.0 - t
}

let n 1000000
var pi: double 0.0
for k in n
    pi := pi + term(k)
print "`n` terms of Leibniz's series: pi is about `pi`"
